namespace Payments;

public sealed class PaymentGateway
{
    private readonly Dictionary<string, decimal> _charges = new();

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        if (amount > 999_999.99m)
            return Task.FromResult(new ChargeResult(string.Empty, Success: false, "Amount exceeds maximum."));

        var chargeId = Guid.NewGuid().ToString("N");
        _charges[chargeId] = amount;
        return Task.FromResult(new ChargeResult(chargeId, Success: true, Message: null));
    }

    public Task<RefundResult> RefundAsync(string chargeId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        if (!_charges.Remove(chargeId, out var amount))
            return Task.FromResult(new RefundResult(string.Empty, Success: false, "Charge not found."));

        var refundId = Guid.NewGuid().ToString("N");
        return Task.FromResult(new RefundResult(refundId, Success: true, Message: null));
    }

    public Task<WebhookResult> ProcessWebhookAsync(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        var handled = eventType switch
        {
            "charge.succeeded" or "charge.failed" or "refund.completed" => true,
            _ => false,
        };

        return Task.FromResult(new WebhookResult(handled, eventType));
    }
}

public record ChargeResult(string ChargeId, bool Success, string? Message);
public record RefundResult(string RefundId, bool Success, string? Message);
public record WebhookResult(bool Handled, string EventType);

