using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup() => _gateway = new PaymentGateway();

    // ── ChargeAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.ChargeId));
        Assert.IsNull(result.Message);
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumPositiveAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MaxAllowedAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 1_000_000.00m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
        Assert.IsNotNull(result.Message);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public async Task ChargeAsync_ZeroAmount_Throws()
    {
        await _gateway.ChargeAsync("tok_visa", 0m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public async Task ChargeAsync_NegativeAmount_Throws()
    {
        await _gateway.ChargeAsync("tok_visa", -10m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_NullToken_Throws()
    {
        await _gateway.ChargeAsync(null!, 10m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_EmptyToken_Throws()
    {
        await _gateway.ChargeAsync("", 10m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_WhitespaceToken_Throws()
    {
        await _gateway.ChargeAsync("   ", 10m);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnUniqueIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_a", 10m);
        var r2 = await _gateway.ChargeAsync("tok_b", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    // ── RefundAsync ─────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ExistingCharge_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_visa", 25m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrEmpty(refund.RefundId));
        Assert.IsNull(refund.Message);
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentCharge_ReturnsFailure()
    {
        var refund = await _gateway.RefundAsync("nonexistent_id");

        Assert.IsFalse(refund.Success);
        Assert.AreEqual(string.Empty, refund.RefundId);
        Assert.IsNotNull(refund.Message);
    }

    [TestMethod]
    public async Task RefundAsync_DoubleRefund_SecondFails()
    {
        var charge = await _gateway.ChargeAsync("tok_visa", 100m);
        await _gateway.RefundAsync(charge.ChargeId);

        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(second.Success);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_NullChargeId_Throws()
    {
        await _gateway.RefundAsync(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_EmptyChargeId_Throws()
    {
        await _gateway.RefundAsync("");
    }

    // ── ProcessWebhookAsync ─────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded")]
    [DataRow("charge.failed")]
    [DataRow("refund.completed")]
    public async Task ProcessWebhookAsync_KnownEvent_IsHandled(string eventType)
    {
        var result = await _gateway.ProcessWebhookAsync(eventType, "{\"id\":\"evt_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual(eventType, result.EventType);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_UnknownEvent_IsNotHandled()
    {
        var result = await _gateway.ProcessWebhookAsync("unknown.event", "{}");

        Assert.IsFalse(result.Handled);
        Assert.AreEqual("unknown.event", result.EventType);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ProcessWebhookAsync_NullEventType_Throws()
    {
        await _gateway.ProcessWebhookAsync(null!, "{}");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ProcessWebhookAsync_NullPayload_Throws()
    {
        await _gateway.ProcessWebhookAsync("charge.succeeded", null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ProcessWebhookAsync_EmptyPayload_Throws()
    {
        await _gateway.ProcessWebhookAsync("charge.succeeded", "");
    }
}

